pub type Point = [f64; 2];
pub type Ring = Vec<Point>;
pub type Polygon = Vec<Ring>;

pub fn build_polygon(n: i32) -> Polygon {
    let mut polygon = Vec::new();

    if n <= 0 {
        return polygon;
    }

    for i in 0..n {
        let offset = f64::from(i) * 2.0;
        let size = f64::from(n);
        let ring = vec![
            [offset, offset],
            [offset + size, offset],
            [offset + size, offset + size],
            [offset, offset + size],
        ];
        polygon.push(ring);
    }

    polygon
}

#[cfg(test)]
mod tests {
    use super::build_polygon;

    #[test]
    fn builds_expected_square_rings() {
        let polygon = build_polygon(2);
        assert_eq!(polygon.len(), 2);
        assert_eq!(polygon[0], vec![[0.0, 0.0], [2.0, 0.0], [2.0, 2.0], [0.0, 2.0]]);
        assert_eq!(polygon[1], vec![[2.0, 2.0], [4.0, 2.0], [4.0, 4.0], [2.0, 4.0]]);
    }
}

